}"}], "structured_content": {"result": {"id": 127688, "name": "taylor_isLittleO_univ", "source_text": "theorem taylor_isLittleO_univ {f : ℝ → E} {x₀ : ℝ} {n : ℕ} (hf : ContDiff ℝ n f) :
